!function(t){function r(r){for(var n,a,o=r[0],s=r[1],p=r[2],c=0,g=[];c<o.length;c++)a=o[c],Object.prototype.hasOwnProperty.call(i,a)&&i[a]&&g.push(i[a][0]),i[a]=0;for(n in s)Object.prototype.hasOwnProperty.call(s,n)&&(t[n]=s[n]);for(u&&u(r);g.length;)g.shift()();return m.push.apply(m,p||[]),e()}function e(){for(var t,r=0;r<m.length;r++){for(var e,a=m[r],o=!0,s=1;s<a.length;s++)e=a[s],0!==i[e]&&(o=!1);o&&(m.splice(r--,1),t=n(n.s=a[0]))}return t}function n(r){if(a[r])return a[r].exports;var e=a[r]={i:r,l:!1,exports:{}};return t[r].call(e.exports,e,e.exports,n),e.l=!0,e.exports}var a={},i={8:0},m=[];n.m=t,n.c=a,n.d=function(t,r,e){n.o(t,r)||Object.defineProperty(t,r,{enumerable:!0,get:e})},n.r=function(t){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(t,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(t,"__esModule",{value:!0})},n.t=function(t,r){if(1&r&&(t=n(t)),8&r)return t;if(4&r&&"object"==typeof t&&t&&t.__esModule)return t;var e=Object.create(null);if(n.r(e),Object.defineProperty(e,"default",{enumerable:!0,value:t}),2&r&&"string"!=typeof t)for(var a in t)n.d(e,a,function(r){return t[r]}.bind(null,a));return e},n.n=function(t){var r=t&&t.__esModule?function(){return t.default}:function(){return t};return n.d(r,"a",r),r},n.o=function(t,r){return Object.prototype.hasOwnProperty.call(t,r)},n.p="";var o=window.webpackJsonp=window.webpackJsonp||[],s=o.push.bind(o);o.push=r,o=o.slice();for(var p=0;p<o.length;p++)r(o[p]);var u=s;m.push([27,0]),e()}({27:function(t,r,e){"use strict";e.r(r);var n=e(0);Object(n.a)("us","army",e(28),e(1))},28:function(t){t.exports=JSON.parse('{"category":[{"name":"美国","link":"us_shortcut"},{"name":"陆战武器","link":"us_army"},{"name":"坦克","link":"us_army#us_army_tank"}],"model":"M26重型坦克","description":"<h6>综述：</h6><p>美国在1942年开始研制重型坦克，最早型号为T1E2，经过多个T型号试验坦克的改进，1945年1月将20辆试验坦克T26E3运往欧洲战场，在2月的实战中表现令美军感到满意，于是3月开始量产并重新定型为M26，取名“潘兴”（美国一战中的一位将军名）；至1945年底，M26“潘兴”重型坦克一共生产了2000多辆（其中900多辆为二战结束后生产），但最后只有300多辆分配到战场上的美军装甲部队，其中仅有20辆参加过实战（M26“潘兴”重型坦克真正发挥作用是在朝鲜战场上）。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{text}}M26“潘兴”重型坦克{{image}}imgs/us/army/us_army_tankm26_11.jpg{{text}}1945年5月德国，美军第3装甲师第33坦克营的M26“潘兴”重型坦克。{{image}}imgs/us/army/us_army_tankm26_12.jpg{{text}}1945年5月在波西米亚地区，美军某装甲师第18坦克营的M26“潘兴”重型坦克。{{image}}imgs/us/army/us_army_tankm26_13.jpg{{text}}1945年2月在德国，美军第3装甲师第33坦克营的T26E3重型坦克（M26的前身试验车型）。{{image}}imgs/us/army/us_army_tankm26_14.jpg","description":"<h6>M26“潘兴”重型坦克</h6><p>该坦克装备了穿透力强的90mmM3火炮（可在1000米距离击穿147mm装甲），其车体为焊接结构，炮塔和车体前、后部份为铸件；防护装甲除车体下部较薄外（19mm）其它部分厚度为51-120mm；动力采用了福特公司V形8缸大功率汽油机，可靠性和机动性都超过当时其它参战国的重型坦克。</p><p>坦克参数：</p><p>车长：8.65m，车宽：3.51m，车高：2,78m，车重：41.9t，发动机功率：300匹马力，最高车速：40km/h，最大行程：161km；乘员：5人；武器配备：一门90mmM3火炮，2挺7.62mm口径机枪，一挺12.7mm口径高射机枪。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>传统的单炮塔，装备带制退器的长身管火炮。</li><li>采用扭杆悬挂系统，系统两侧各有负重轮6个。</li><li>配备高射机枪。</li></ol></span>","caption":""}],"part2title":"战场上的M26“潘兴”重型坦克","part2description":"<p>M26“潘兴”重型坦克量产后，有300多辆装备给欧洲战场上的美军第3和第11装甲师，但此时二战已快结束，美军已攻入德国，战事不多，所以只有大约20辆M26与德军的“豹”式和“虎”坦克交过手，互有胜负。在1942年2月，隶属美军第3装甲师第33装甲团F连的一辆M26在途经德国城镇埃尔斯多夫时，被一辆德军虎式坦克伏击，M26坦克被3发穿甲弹击中，致使坦克乘员全部死亡。但该团E连的40号车组在接着的战斗中，同样用穿甲弹击毁了德军一辆虎式坦克和2辆4号坦克，杀死了德军坦克乘员，为战友报了仇。在1945年3月，同是第33坦克团，先后有2辆M26被德军反坦克火炮击毁。后在进攻科隆的战斗中，第3装甲师第32装甲团E连的M26坦克在科隆大教堂前击毁了一辆防守的豹式坦克，此后也有一些零星的交火，直到二战欧洲战事结束。M26在亚洲战场基本没有发挥作用，后随美军进驻日本。</p>","part2content":[{"image":"imgs/us/army/us_army_tankm26_21.jpg","description":"1945年1月，在比利时Antwerp码头，正从运输船上吊下一辆刚运抵欧洲的美军M26“潘兴”重型坦克。","caption":""},{"image":"imgs/us/army/us_army_tankm26_22.jpg","description":"1945年春，隶属于美军第3装甲师的M26“潘兴”重型坦克行进在德国马格德堡的街道上，路旁是正在起火的市政厅。","caption":""},{"image":"imgs/us/army/us_army_tankm26_23.jpg","description":"1945年春，在德国作战的一辆美军M26“潘兴”重型坦克，坦克防护装甲上还留有弹孔。","caption":""},{"image":"imgs/us/army/us_army_tankm26_24.jpg","description":"1945年春，在德国，美军一辆M26“潘兴”重型坦克掩护步兵沿城市街道前进。","caption":""},{"image":"imgs/us/army/us_army_tankm26_25.jpg","description":"3个美军士兵正在探雷，为一队M26“潘兴”重型坦克开辟前进道路。","caption":""},{"image":"imgs/us/army/us_army_tankm26_26.jpg","description":"一队M26“潘兴”重型坦克正在树林中集结待命。","caption":""},{"image":"imgs/us/army/us_army_tankm26_27.jpg","description":"一辆在灌木丛林中隐蔽的美军M26“潘兴”重型坦克。","caption":""},{"image":"imgs/us/army/us_army_tankm26_28.jpg","description":"一辆在小山坡上行进的美军M26“潘兴”重型坦克。","caption":""},{"image":"imgs/us/army/us_army_tankm26_29.jpg","description":"一辆搭载多名美军士兵作行进测试的M26“潘兴”重型坦克。","caption":""}]}')}});